import { createHash, timingSafeEqual } from "node:crypto";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// The dashboard HTML is not in the public site folder. This function
// reads it and only sends it after the Netlify password check passes.
function loadPage() {
  const besideFunction = join(dirname(fileURLToPath(import.meta.url)), "admin.html");
  const fromProjectRoot = join(process.cwd(), "netlify/functions/admin.html");
  for (const path of [besideFunction, fromProjectRoot]) {
    try {
      return readFileSync(path, "utf8");
    } catch {
      // try the next location
    }
  }
  return null;
}


// Fallback copy of admin.html, so the dashboard still loads if the
// deploy bundler does not ship the separate HTML file.
const EMBEDDED_PAGE = Buffer.from("", "base64").toString("utf8");

const page = loadPage() || EMBEDDED_PAGE;


function passwordsMatch(given, expected) {
  const a = createHash("sha256").update(given, "utf8").digest();
  const b = createHash("sha256").update(expected, "utf8").digest();
  return timingSafeEqual(a, b);
}

function text(status, body, extra = {}) {
  return new Response(body, {
    status,
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "cache-control": "no-store",
      "x-robots-tag": "noindex, nofollow",
      "x-content-type-options": "nosniff",
      ...extra,
    },
  });
}

function configuredPassword() {
  const password = process.env.ADMIN_PASSWORD || "";
  if (password.length < 8) return null;
  if (password.toLowerCase() === "burrow") return null;
  return password;
}

export default async function handler(request) {
  if (!page) {
    return text(503, "NearBase HQ is locked because the dashboard file did not deploy. Connect this GitHub repo in Netlify and publish the site folder.");
  }

  const expected = configuredPassword();
  if (!expected) {
    return text(
      503,
      "NearBase HQ is locked. In Netlify, add an environment variable named ADMIN_PASSWORD. Use a private password at least 8 characters long, and do not reuse the old passcode that used to be printed on this page. Then redeploy."
    );
  }

  const header = request.headers.get("authorization") || "";
  let ok = false;
  if (/^Basic\s+/i.test(header)) {
    try {
      const decoded = Buffer.from(header.replace(/^Basic\s+/i, ""), "base64").toString("utf8");
      const splitAt = decoded.indexOf(":");
      const given = splitAt >= 0 ? decoded.slice(splitAt + 1) : "";
      ok = passwordsMatch(given, expected);
    } catch {
      ok = false;
    }
  }

  if (!ok) {
    return text(401, "Sign in to open NearBase HQ.", {
      "www-authenticate": 'Basic realm="NearBase HQ", charset="UTF-8"',
    });
  }

  return new Response(page, {
    status: 200,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "x-robots-tag": "noindex, nofollow",
      "x-content-type-options": "nosniff",
      "referrer-policy": "no-referrer",
    },
  });
}
